    body = "make #3 twelve\n\nOn Mon, Nov 2, 2026 at 7:10 AM Lena <l@x.example> wrote:\n> 1. 6 ea flange\n> 2. 6 ea gasket\n"
    assert not run(body)["needs_review"]


